200	function percentDecode(input: Buffer): Buffer {
201	  const out = Buffer.alloc(input.length);
202	  let n = 0;
203	  for (let i = 0; i < input.length; i++) {
204	    const byte = input[i]!;
205	    if (byte !== 0x25 /* % */) {
206	      out[n++] = byte;
207	      continue;
208	    }
209	    const hex = input.subarray(i + 1, i + 3).toString("latin1");
210	    if (!/^[0-9a-fA-F]{2}$/.test(hex)) {
211	      throw new InvalidKeyError("key contains a malformed percent-escape");
212	    }
213	    out[n++] = parseInt(hex, 16);
214	    i += 2;
