389	    const eq = arg.indexOf("=");
390	    const name = arg.startsWith("--") && eq !== -1 ? arg.slice(0, eq) : arg;
391	    let value: string | undefined;
392	    if (name === "--data-dir" || name === "--port") {
393	      if (eq !== -1 && arg.startsWith("--")) {
394	        value = arg.slice(eq + 1);
395	      } else {
