524	/**
525	 * Makes sure the data directory exists and is a writable directory, so that
526	 * misconfiguration is reported at startup rather than on the first request.
527	 */
528	export async function prepareDataDir(dataDir: string): Promise<void> {
529	  await mkdir(dataDir, { recursive: true });
530	  const info = await stat(dataDir);
531	  if (!info.isDirectory()) {
532	    throw new Error(`data dir is not a directory: ${dataDir}`);
533	  }
534	  await access(dataDir, fsConstants.R_OK | fsConstants.W_OK);
535	}
