537	export function createRequestHandler(config: ServerConfig): http.RequestListener {
538	  const store = new BlobStore(config.dataDir);
539	  return (req, res) => {
540	    route(store, req, res).catch((err: unknown) => {
541	      console.error("unhandled error while serving request:", err);
542	      if (!res.headersSent) {
543	        sendJson(res, 500, { error: "internal server error" });
544	      } else {
545	        res.destroy();
546	      }
547	    });
548	  };
549	}
550	
551	async function route(store: BlobStore, req: http.IncomingMessage, res: http.ServerResponse): Promise<void> {
552	  // Raw path without the query string. Deliberately not normalized via URL:
553	  // blob keys must be validated as sent, not after the dot segments have
554	  // been silently resolved.
555	  const path = (req.url ?? "").split("?", 1)[0]!;
556	
557	  if (path === "/healthz") {
558	    if (req.method === "GET" || req.method === "HEAD") {
559	      sendJson(res, 200, { status: "ok" });
560	    } else {
561	      res.setHeader("Allow", "GET, HEAD");
562	      sendJson(res, 405, { error: "method not allowed" });
563	    }
564	    return;
565	  }
566	
567	  if (path === "/blobs") {
568	    if (req.method === "GET" || req.method === "HEAD") {
569	      sendJson(res, 200, await store.list());
570	    } else {
571	      res.setHeader("Allow", "GET, HEAD");
572	      sendJson(res, 405, { error: "method not allowed" });
573	    }
574	    return;
575	  }
576	
577	  if (path.startsWith("/blobs/") && req.method === "PUT") {
578	    try {
579	      const key = parseKey(path.slice("/blobs/".length));
580	      sendJson(res, 201, await store.put(key, req));
581	    } catch (err) {
582	      if (!(err instanceof InvalidKeyError)) throw err;
583	      sendJson(res, 400, { error: err.message });
584	    }
585	    return;
586	  }
587	
588	  sendJson(res, 404, { error: "not found" });
589	}
590	
591	function sendJson(res: http.ServerResponse, status: number, body: unknown): void {
592	  const payload = JSON.stringify(body);
593	  res.writeHead(status, {
594	    "Content-Type": "application/json; charset=utf-8",
595	    "Content-Length": Buffer.byteLength(payload),
596	  });
597	  res.end(payload);
598	}
599	
600	export async function startServer(config: ServerConfig, options: StartOptions = {}): Promise<RunningServer> {
601	  await prepareDataDir(config.dataDir);
602	
603	  const server = http.createServer(createRequestHandler(config));
604	
605	  // Malformed HTTP must never take the process down: answer 400 and drop
606	  // the connection.
607	  server.on("clientError", (err: NodeJS.ErrnoException, socket) => {
608	    if (err.code === "ECONNRESET" || !socket.writable) {
609	      socket.destroy();
610	      return;
611	    }
612	    socket.end("HTTP/1.1 400 Bad Request\r\nConnection: close\r\nContent-Length: 0\r\n\r\n");
613	  });
614	
615	  await new Promise<void>((resolve, reject) => {
616	    server.once("error", reject);
617	    const onListening = (): void => {
618	      server.off("error", reject);
619	      resolve();
620	    };
621	    if (options.host === undefined) {
622	      server.listen(config.port, onListening);
623	    } else {
624	      server.listen(config.port, options.host, onListening);
625	    }
626	  });
627	
628	  const shutdownTimeoutMs = options.shutdownTimeoutMs ?? 5000;
629	  let closing: Promise<void> | undefined;
630	
631	  return {
632	    server,
633	    port: (server.address() as AddressInfo).port,
634	    close() {
635	      closing ??= new Promise<void>((resolve, reject) => {
636	        const timer = setTimeout(() => server.closeAllConnections(), shutdownTimeoutMs);
637	        timer.unref();
638	        server.close((err) => {
639	          clearTimeout(timer);
640	          if (err) reject(err);
641	          else resolve();
642	        });
643	        server.closeIdleConnections();
644	      });
645	      return closing;
646	    },
647	  };
648	}
