  it("PUT answers 400 for raw non-UTF-8 bytes in the path", async () => {
    const status = await rawStatus("PUT", Buffer.concat([Buffer.from("/blobs/"), Buffer.from([0xff, 0xfe])]));
    assert.equal(status, 400);
