      "/blobs/%2e%2e/escape",
      "/blobs/%2E%2E%2Fescape",
      "/blobs//etc/passwd",
      "/blobs/%2Fetc%2Fpasswd",
      "/blobs/a//b",
      "/blobs/a/",
      "/blobs/./a",
      "/blobs/%00",
      "/blobs/%",
      "/blobs/%zz",
      "/blobs/%FF",
      "/blobs/%ED%A0%80",
      `/blobs/${"a".repeat(256)}`,
    ]) {
      const res = await request("PUT", path, "x");
      assert.equal(res.status, 400, path);
    }
    assert.deepEqual(await readdir(root), before);
  });

